function captureIo(env: NodeJS.ProcessEnv = {}) {
  let stdout = "";
  let stderr = "";
  return {
    io: {
      env,
      stdout: {
        write: (value: string | Uint8Array) => ((stdout += value), true),
      },
      stderr: {
        write: (value: string | Uint8Array) => ((stderr += value), true),
      },
    },
    stdout: () => stdout,
    stderr: () => stderr,
  };
}

